package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.ProductRequest;import com.digitalbase.ticketing.dto.ProductResponse;import com.digitalbase.ticketing.exception.DuplicateResourceException; // 👈 အသစ်import com.digitalbase.ticketing.exception.FileStorageException; // 👈 အသစ်import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.model.Product;import com.digitalbase.ticketing.repository.ProductRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.io.File;import java.io.IOException;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.nio.file.StandardCopyOption;import java.util.List;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class ProductServiceImpl implements ProductService {    private final ProductRepository productRepository;    private final String UPLOAD_DIR = "uploads/";    @Override    public ProductResponse createProduct(ProductRequest request) {        // 👉 DuplicateResourceException ဖြင့် အစားထိုးထားသည်        if (productRepository.existsByName(request.getName())) {            throw new DuplicateResourceException("Product with name '" + request.getName() + "' already exists.");        }        String imageUrl = saveImage(request.getImage());        Product product = Product.builder()                .name(request.getName())                .description(request.getDescription())                .productType(request.getProductType())                .imageUrl(imageUrl)                .status(request.getStatus())                .build();        Product savedProduct = productRepository.save(product);        return mapToResponse(savedProduct);    }    @Override    public ProductResponse updateProduct(Long id, ProductRequest request) {        Product product = productRepository.findById(id)                .orElseThrow(() -> new ResourceNotFoundException("Product not found with id: " + id));        // 👉 DuplicateResourceException ဖြင့် အစားထိုးထားသည်        if (!product.getName().equalsIgnoreCase(request.getName()) && productRepository.existsByName(request.getName())) {            throw new DuplicateResourceException("Product with name '" + request.getName() + "' already exists.");        }        product.setName(request.getName());        product.setDescription(request.getDescription());        product.setProductType(request.getProductType());        product.setStatus(request.getStatus());        if (request.getImage() != null && !request.getImage().isEmpty()) {            product.setImageUrl(saveImage(request.getImage()));        }        Product updatedProduct = productRepository.save(product);        return mapToResponse(updatedProduct);    }    @Override    public List<ProductResponse> getAllProducts() {        return productRepository.findAll().stream().map(this::mapToResponse).collect(Collectors.toList());    }    @Override    public ProductResponse getProductById(Long id) {        Product product = productRepository.findById(id)                .orElseThrow(() -> new ResourceNotFoundException("Product not found with id: " + id));        return mapToResponse(product);    }    @Override    public void deleteProduct(Long id) {        Product product = productRepository.findById(id)                .orElseThrow(() -> new ResourceNotFoundException("Product not found with id: " + id));        productRepository.delete(product);    }    private ProductResponse mapToResponse(Product product) {        return ProductResponse.builder()                .id(product.getId())                .name(product.getName())                .description(product.getDescription())                .productType(product.getProductType())                .imageUrl(product.getImageUrl())                .status(product.getStatus())                .createdAt(product.getCreatedAt())                .build();    }    private String saveImage(MultipartFile file) {        if (file == null || file.isEmpty()) return null;        try {            File dir = new File(UPLOAD_DIR);            if (!dir.exists()) dir.mkdirs();            String fileName = System.currentTimeMillis() + "_" + file.getOriginalFilename().replaceAll("\\s+", "_");            Path filePath = Paths.get(UPLOAD_DIR + fileName);            Files.copy(file.getInputStream(), filePath, StandardCopyOption.REPLACE_EXISTING);            return "/uploads/" + fileName;        } catch (IOException e) {            // 👉 fileName အစား file.getOriginalFilename() ကို သုံးလိုက်ပါသည်            throw new FileStorageException("Failed to store image file: " + file.getOriginalFilename(), e);        }    }}